namespace cwhip {

std::string CodeGenerator::inlineSymbol(const Statement& statement) const {
    std::uint64_t hash = 14695981039346656037ULL;
    for (const unsigned char value : statement.location.file) {
        hash ^= value;
        hash *= 1099511628211ULL;
    }
    for (const auto value : {statement.location.line, statement.location.column}) {
        hash ^= static_cast<std::uint64_t>(value);
        hash *= 1099511628211ULL;
    }
    std::ostringstream name;
    name << "cwhip_inline_" << std::hex << hash;
    return name.str();
}

void CodeGenerator::emitInlineC(const Statement& statement) {
    const auto symbol = inlineSymbol(statement);
    std::string llvmArguments;
    std::string cParameters;
    for (const auto& capture : statement.inlineCaptures) {
        const auto binding = capture.target && capture.target->kind == ExpressionKind::Member
            ? emitFieldBinding(*capture.target)
            : findVariable(capture.name, capture.location);
        if (!llvmArguments.empty()) {
            llvmArguments += ", ";
            cParameters += ", ";
        }
        llvmArguments += "ptr " + emitAddress(binding, capture.location);
        if (capture.type == "int") {
            cParameters += "int64_t *" + capture.name;
        } else if (capture.type == "bool") {
            cParameters += "_Bool *" + capture.name;
        } else if (capture.type == "float") {
            cParameters += "double *" + capture.name;
        } else if (capture.type == "unsigned") {
            cParameters += "uint64_t *" + capture.name;
        } else if (isBufferType(capture.type)) {
            // Buffers are managed references: the shim receives the address of
            // the variable's slot, so inline C works with the live buffer
            // directly rather than a copy.
            cParameters += "CwhipBuffer **" + capture.name;
        } else {
            cParameters += "void **" + capture.name;
        }
    }
    if (declaredInlineSymbols_.emplace(symbol).second) {
        std::string declarationArguments;
        for (std::size_t index = 0; index < statement.inlineCaptures.size(); ++index) {
            if (index != 0) declarationArguments += ", ";
            declarationArguments += "ptr";
        }
        inlineDeclarations_ += "declare void @" + symbol + "(" +
                               declarationArguments + ")\n";

        const auto parameters = cParameters.empty() ? "void" : cParameters;
        std::string definition = "void " + symbol + "(" + parameters + ") {\n"
                                 "    cwhip_inline_cstr_begin();\n";
        definition += statement.inlineSource;
        if (definition.empty() || definition.back() != '\n') definition += '\n';
        definition += "    cwhip_inline_cstr_end();\n}\n";
        inlineShims_.emplace(symbol, std::move(definition));
    }
    instructions_ += "  call void @" + symbol + "(" + llvmArguments + ")\n";
}

void CodeGenerator::emitStatements(const std::vector<Statement>& statements) {
    for (const auto& statement : statements) {
        if (blockTerminated_) continue;
        if (debug_) {
            const auto previous = debugCurrentLocation_;
            debugCurrentLocation_ = debugLocation(statement.location);
            instructions_ += "; cwhip.debug.location " + debugCurrentLocation_ + "\n";
            emitStatement(statement);
            instructions_ += "; cwhip.debug.location " + previous + "\n";
            debugCurrentLocation_ = previous;
        } else {
            emitStatement(statement);
        }
    }
}

void CodeGenerator::emitLoopTransfer(bool isBreak, const SourceLocation& location) {
    if (loopTargets_.empty()) {
        throw DiagnosticError(location,
                              isBreak ? "'break' outside of a loop"
                                      : "'continue' outside of a loop");
    }
    const auto target = loopTargets_.back();
    const auto savedTryTransfers = activeTryTransfers_;
    const auto savedExceptionHandlers = activeExceptionHandlers_;
    while (activeTryTransfers_.size() > target.tryDepth) {
        const auto active = activeTryTransfers_.back();
        activeTryTransfers_.pop_back();
        if (active.exceptionFrameActive) {
            instructions_ += "  call void @cwhip_exception_pop(ptr " +
                             active.exceptionFrame + ")\n";
        }
        if (!active.handledExceptionFrame.empty()) {
            instructions_ += "  call void @cwhip_exception_clear(ptr " +
                             active.handledExceptionFrame + ")\n"
                             "  store ptr null, ptr " + active.handledExceptionRoot + "\n";
            activeExceptionHandlers_.pop_back();
        }
        if (active.cleanup != nullptr) {
            scopes_.emplace_back();
            blockTerminated_ = false;
            emitStatements(*active.cleanup);
            const bool cleanupTerminated = blockTerminated_;
            scopes_.pop_back();
            if (cleanupTerminated) {
                activeTryTransfers_ = savedTryTransfers;
                activeExceptionHandlers_ = savedExceptionHandlers;
                return;
            }
        }
    }
    instructions_ += "  br label %" + (isBreak ? target.breakLabel : target.continueLabel) +
                     "\n";
    blockTerminated_ = true;
    activeTryTransfers_ = savedTryTransfers;
    activeExceptionHandlers_ = savedExceptionHandlers;
}

void CodeGenerator::emitStatement(const Statement& statement) {
    switch (statement.kind) {
    case StatementKind::Declaration: {
        const auto pointer = "%v" + std::to_string(nextVariable_++);
        std::string flagPointer;
        const bool nullableScalar = isNullableScalarType(statement.declaredType);
        if (nullableScalar) {
            flagPointer = "%v" + std::to_string(nextVariable_++) + ".isnull";
        }
        scopes_.back().emplace(statement.name,
                               Binding{statement.declaredType, pointer, {}, false, false,
                                      flagPointer});
        entryAllocas_ += "  " + pointer + " = alloca " + llvmType(statement.declaredType) + "\n";
        if (nullableScalar) entryAllocas_ += "  " + flagPointer + " = alloca i1\n";
        registerRootSlot(pointer, statement.declaredType);
        instructions_ += debugDeclaration(statement.name, statement.declaredType, pointer,
                                          statement.location);
        if (!statement.expressions.empty()) {
            auto value = emitExpression(*statement.expressions.front(), statement.declaredType);
            auto converted = convertObjectValue(value, statement.declaredType,
                                                 statement.expressions.front()->location);
            converted = copyBufferValue(std::move(converted),
                                        statement.expressions.front()->location);
            instructions_ += "  store " + llvmType(statement.declaredType) + " " +
                             converted.operand + ", ptr " + pointer + "\n";
            if (nullableScalar) {
                instructions_ += "  store i1 " +
                                 (converted.nullFlag.empty() ? "0" : converted.nullFlag) +
                                 ", ptr " + flagPointer + "\n";
            }
        } else {
            instructions_ += "  store " + llvmType(statement.declaredType) +
                             " zeroinitializer, ptr " + pointer + "\n";
            if (nullableScalar) instructions_ += "  store i1 0, ptr " + flagPointer + "\n";
        }
        return;
    }
    case StatementKind::Assignment: {
        Binding binding;
        std::string address;
        bool arrayElementTarget = false;
        bool mapElementTarget = false;
        bool bufferElementTarget = false;
        std::string mapPointer;
        std::string bufferPointer;
        Value bufferIndex;
        std::string arrayPointer;
        std::string arrayIndex;
        Value mapKey;
        Value compoundLeft;
        if (statement.target->kind == ExpressionKind::Identifier) {
            binding = findVariable(statement.target->value, statement.target->location);
            address = emitAddress(binding, statement.location);
        } else if (statement.target->kind == ExpressionKind::Index) {
            binding.type = "any";
            const auto collection = emitExpression(*statement.target->left);
            if (isArrayType(collection.type)) {
                const auto index =
                    emitIntegerExpression(*statement.target->arguments.front());
                arrayPointer = collection.operand;
                arrayIndex = index.operand;
                const auto file = internString(statement.target->location.file);
                address = newTemporary();
                instructions_ += "  " + address + " = call ptr @cwhip_array_index(ptr " +
                                 collection.operand + ", i64 " + index.operand + ", ptr " +
                                 file + ", i64 " +
                                 std::to_string(statement.target->location.file.size()) +
                                 ", i64 " +
                                 std::to_string(statement.target->location.line) + ", i64 " +
                                 std::to_string(statement.target->location.column) + ")\n";
                arrayElementTarget = true;
            } else if (isBufferType(collection.type)) {
                bufferPointer = collection.operand;
                bufferIndex = emitIntegerExpression(*statement.target->arguments.front());
                binding.type = "buffer-byte";
                bufferElementTarget = true;
            } else {
                mapPointer = collection.operand;
                mapKey = emitExpression(*statement.target->arguments.front());
                mapElementTarget = true;
            }
        } else {
            binding = emitFieldBinding(*statement.target);
            address = binding.pointer;
        }
        const bool compoundAssignment = statement.assignmentOperator != "=";
        if (compoundAssignment) {
            const auto loaded = newTemporary();
            instructions_ += "  " + loaded + " = load " + llvmType(binding.type) +
                             ", ptr " + address + "\n";
            compoundLeft = {binding.type, loaded};
        }
        auto value = emitExpression(*statement.expressions.front(),
                                    compoundAssignment ? "" : binding.type);
        if (compoundAssignment) {
            const auto operation = statement.assignmentOperator.substr(
                0, statement.assignmentOperator.size() - 1);
            value = emitArithmeticOperation(operation, statement.assignmentOperatorLocation,
                                            compoundLeft, value);
        }
        if (arrayElementTarget) {
            // The RHS may resize the array and relocate its elements.
            const auto file = internString(statement.target->location.file);
            address = newTemporary();
            instructions_ += "  " + address + " = call ptr @cwhip_array_index(ptr " +
                             arrayPointer + ", i64 " + arrayIndex + ", ptr " +
                             file + ", i64 " +
                             std::to_string(statement.target->location.file.size()) +
                             ", i64 " + std::to_string(statement.target->location.line) +
                             ", i64 " + std::to_string(statement.target->location.column) + ")\n";
            emitArrayElementStore(address, value, statement.expressions.front()->location);
            return;
        }
        if (mapElementTarget) {
            emitMapElementStore(mapPointer, mapKey, value, statement.target->location);
            return;
        }
        if (bufferElementTarget) {
            const auto& value64 = value.operand;
            const auto file = internString(statement.target->location.file);
            instructions_ += "  call void @cwhip_buffer_set(ptr " + bufferPointer + ", i64 " +
                             bufferIndex.operand + ", i64 " + value64 + ", ptr " + file +
                             ", i64 " +
                             std::to_string(statement.target->location.file.size()) + ", i64 " +
                             std::to_string(statement.target->location.line) + ", i64 " +
                             std::to_string(statement.target->location.column) + ")\n";
            return;
        }
        auto converted = convertObjectValue(value, binding.type,
                                            statement.expressions.front()->location);
        converted = copyBufferValue(std::move(converted),
                                    statement.expressions.front()->location);
        instructions_ += "  store " + llvmType(binding.type) + " " + converted.operand +
                         ", ptr " + address + "\n";
        if (!binding.nullFlagAddress.empty()) {
            instructions_ += "  store i1 " +
                             (converted.nullFlag.empty() ? "0" : converted.nullFlag) +
                             ", ptr " + binding.nullFlagAddress + "\n";
        }
        return;
    }
    case StatementKind::Print:
        emitPrint(statement);
        return;
    case StatementKind::Expression:
        (void)emitExpression(*statement.expressions.front());
        return;
    case StatementKind::InlineC:
        emitInlineC(statement);
        return;
    case StatementKind::Return: {
        std::string result;
        if (!statement.expressions.empty()) {
            const auto value = emitExpression(*statement.expressions.front(),
                                              currentMethod_->returnType);
            const auto converted = convertObjectValue(value, currentMethod_->returnType,
                                                       statement.expressions.front()->location);
            result = rootObjectValue(converted, statement.expressions.front()->location).operand;
        }
        const auto savedTryTransfers = activeTryTransfers_;
        const auto savedExceptionHandlers = activeExceptionHandlers_;
        while (!activeTryTransfers_.empty()) {
            const auto active = activeTryTransfers_.back();
            activeTryTransfers_.pop_back();
            if (active.exceptionFrameActive) {
                instructions_ += "  call void @cwhip_exception_pop(ptr " +
                                 active.exceptionFrame + ")\n";
            }
            if (!active.handledExceptionFrame.empty()) {
                instructions_ += "  call void @cwhip_exception_clear(ptr " +
                                 active.handledExceptionFrame + ")\n"
                                 "  store ptr null, ptr " + active.handledExceptionRoot + "\n";
                activeExceptionHandlers_.pop_back();
            }
            if (active.cleanup != nullptr) {
                scopes_.emplace_back();
                blockTerminated_ = false;
                emitStatements(*active.cleanup);
                scopes_.pop_back();
                if (blockTerminated_) {
                    activeTryTransfers_ = savedTryTransfers;
                    activeExceptionHandlers_ = savedExceptionHandlers;
                    return;
                }
            }
        }
        emitRootFramePop();
        instructions_ += statement.expressions.empty()
                             ? "  ret void\n"
                             : "  ret " + llvmType(currentMethod_->returnType) + " " +
                                   result + "\n";
        blockTerminated_ = true;
        activeTryTransfers_ = savedTryTransfers;
        activeExceptionHandlers_ = savedExceptionHandlers;
        return;
    }
    case StatementKind::SuperConstructorCall: {
        if (statement.virtualBaseInitializer) return;
        const auto base = classes_.find(statement.name);
        if (base == classes_.end()) {
            throw DiagnosticError(statement.location, "unknown base class '" + statement.name + "'");
        }
        const auto* constructor =
            findConstructor(*base->second, statement.resolvedSignature);
        if (constructor == nullptr) return;
        const auto baseIndex = static_cast<std::size_t>(
            std::distance(currentClass_->baseClassNames.begin(),
                          std::find(currentClass_->baseClassNames.begin(),
                                    currentClass_->baseClassNames.end(), statement.name)));
        const auto basePointer = newTemporary();
        instructions_ += "  " + basePointer + " = getelementptr inbounds %Class." +
                         currentClass_->name + ", ptr %this, i32 0, i32 " +
                         std::to_string(baseIndex + 2) + "\n";
        std::string arguments = "ptr " + basePointer + ", i1 false";
        for (std::size_t index = 0; index < statement.expressions.size(); ++index) {
            const auto value = emitExpression(*statement.expressions[index],
                                              constructor->parameters[index].type);
            const auto converted = convertObjectValue(value,
                                                       constructor->parameters[index].type,
                                                       statement.expressions[index]->location);
            arguments += ", " + llvmType(constructor->parameters[index].type) + " " +
                         converted.operand;
        }
        instructions_ += "  call void " + methodSymbol(statement.name, *constructor) +
                         "(" + arguments + ")\n";
        return;
    }
    case StatementKind::Block:
        scopes_.emplace_back();
        emitStatements(statement.body);
        scopes_.pop_back();
        return;
    case StatementKind::If: {
        const auto condition = emitExpression(*statement.expressions.front());
        const auto thenLabel = freshLabel("if.then");
        const auto elseLabel = freshLabel("if.else");
        const auto endLabel = freshLabel("if.end");
        instructions_ += "  br i1 " + condition.operand + ", label %" + thenLabel + ", label %" +
                         (statement.hasAlternate ? elseLabel : endLabel) + "\n";
        instructions_ += thenLabel + ":\n";
        scopes_.emplace_back();
        blockTerminated_ = false;
        emitStatements(statement.body);
        const bool thenTerminated = blockTerminated_;
        scopes_.pop_back();
        if (!thenTerminated) instructions_ += "  br label %" + endLabel + "\n";
        bool elseTerminated = false;
        if (statement.hasAlternate) {
            instructions_ += elseLabel + ":\n";
            scopes_.emplace_back();
            blockTerminated_ = false;
            emitStatements(statement.alternate);
            elseTerminated = blockTerminated_;
            scopes_.pop_back();
            if (!elseTerminated) instructions_ += "  br label %" + endLabel + "\n";
        }
        instructions_ += endLabel + ":\n";
        blockTerminated_ = thenTerminated && statement.hasAlternate && elseTerminated;
        if (blockTerminated_) instructions_ += "  unreachable\n";
        return;
    }
    case StatementKind::While: {
        const auto conditionLabel = freshLabel("while.cond");
        const auto bodyLabel = freshLabel("while.body");
        const auto endLabel = freshLabel("while.end");
        instructions_ += "  br label %" + conditionLabel + "\n" + conditionLabel + ":\n";
        const auto condition = emitExpression(*statement.expressions.front());
        instructions_ += "  br i1 " + condition.operand + ", label %" + bodyLabel +
                         ", label %" + endLabel + "\n";
        instructions_ += bodyLabel + ":\n";
        scopes_.emplace_back();
        loopTargets_.push_back({endLabel, conditionLabel, activeTryTransfers_.size()});
        blockTerminated_ = false;
        emitStatements(statement.body);
        const bool bodyTerminated = blockTerminated_;
        loopTargets_.pop_back();
        scopes_.pop_back();
        if (!bodyTerminated) instructions_ += "  br label %" + conditionLabel + "\n";
        instructions_ += endLabel + ":\n";
        blockTerminated_ = false;
        return;
    }
    case StatementKind::DoWhile: {
        const auto bodyLabel = freshLabel("do.body");
        const auto conditionLabel = freshLabel("do.cond");
        const auto endLabel = freshLabel("do.end");
        instructions_ += "  br label %" + bodyLabel + "\n" + bodyLabel + ":\n";
        scopes_.emplace_back();
        loopTargets_.push_back({endLabel, conditionLabel, activeTryTransfers_.size()});
        blockTerminated_ = false;
        emitStatements(statement.body);
        const bool bodyTerminated = blockTerminated_;
        loopTargets_.pop_back();
        scopes_.pop_back();
        if (!bodyTerminated) instructions_ += "  br label %" + conditionLabel + "\n";
        instructions_ += conditionLabel + ":\n";
        blockTerminated_ = false;
        const auto condition = emitExpression(*statement.expressions.front());
        instructions_ += "  br i1 " + condition.operand + ", label %" + bodyLabel + ", label %" +
                         endLabel + "\n"
                         + endLabel + ":\n";
        blockTerminated_ = false;
        return;
    }
    case StatementKind::ForEach: {
        const auto source = emitExpression(*statement.expressions.front());
        const bool array = isArrayType(source.type);
        const auto lengthAddress = newTemporary();
        const auto length = newTemporary();
        instructions_ += "  " + lengthAddress +
                         " = getelementptr inbounds " +
                         (array ? "%CwhipArray" : "%CwhipMap") + ", ptr " +
                         source.operand + ", i32 0, i32 1\n"
                         "  " + length + " = load i64, ptr " + lengthAddress + "\n";
        const auto snapshot = newTemporary();
        const auto file = internString(statement.location.file);
        const auto sliceFunction = array ? "cwhip_array_slice" : "cwhip_map_slice";
        instructions_ += "  " + snapshot + " = call ptr @" + sliceFunction + "(ptr " +
                         source.operand + ", i64 0, i64 " + length + ", ptr " + file +
                         ", i64 " + std::to_string(statement.location.file.size()) +
                         ", i64 " + std::to_string(statement.location.line) + ", i64 " +
                         std::to_string(statement.location.column) + ")\n";
        const auto collection = rootObjectValue({source.type, snapshot}, statement.location);

        const auto indexSlot = "%v" + std::to_string(nextVariable_++);
        entryAllocas_ += "  " + indexSlot + " = alloca i64\n";
        instructions_ += "  store i64 0, ptr " + indexSlot + "\n";
        scopes_.emplace_back();
        if (!statement.keyName.empty()) {
            const auto keySlot = "%v" + std::to_string(nextVariable_++);
            scopes_.back().emplace(statement.keyName,
                                   Binding{"String", keySlot, {}, false});
            entryAllocas_ += "  " + keySlot + " = alloca ptr\n";
            registerRootSlot(keySlot, "String");
            instructions_ += debugDeclaration(statement.keyName, "String", keySlot,
                                              statement.location);
        }
        const auto valueSlot = "%v" + std::to_string(nextVariable_++);
        scopes_.back().emplace(statement.name, Binding{"any", valueSlot, {}, false});
        entryAllocas_ += "  " + valueSlot + " = alloca %CwhipArrayValue\n";
        registerRootSlot(valueSlot, "any");
        instructions_ += debugDeclaration(statement.name, "any", valueSlot,
                                          statement.location);

        const auto conditionLabel = freshLabel("foreach.cond");
        const auto bodyLabel = freshLabel("foreach.body");
        const auto stepLabel = freshLabel("foreach.step");
        const auto endLabel = freshLabel("foreach.end");
        instructions_ += "  br label %" + conditionLabel + "\n" + conditionLabel + ":\n";
        const auto index = newTemporary();
        const auto inRange = newTemporary();
        instructions_ += "  " + index + " = load i64, ptr " + indexSlot + "\n"
                         "  " + inRange + " = icmp ult i64 " + index + ", " + length + "\n"
                         "  br i1 " + inRange + ", label %" + bodyLabel + ", label %" +
                         endLabel + "\n" + bodyLabel + ":\n";
        if (array) {
            const auto element = newTemporary();
            const auto loaded = newTemporary();
            instructions_ += "  " + element + " = call ptr @cwhip_array_index(ptr " +
                             collection.operand + ", i64 " + index + ", ptr " + file +
                             ", i64 " + std::to_string(statement.location.file.size()) +
                             ", i64 " + std::to_string(statement.location.line) + ", i64 " +
                             std::to_string(statement.location.column) + ")\n"
                             "  " + loaded + " = load %CwhipArrayValue, ptr " + element +
                             "\n"
                             "  store %CwhipArrayValue " + loaded + ", ptr " + valueSlot +
                             "\n";
        } else {
            const auto entry = newTemporary();
            const auto valueAddress = newTemporary();
            const auto value = newTemporary();
            instructions_ += "  " + entry + " = call ptr @cwhip_map_entry_at(ptr " +
                             collection.operand + ", i64 " + index + ", ptr " + file +
                             ", i64 " + std::to_string(statement.location.file.size()) +
                             ", i64 " + std::to_string(statement.location.line) + ", i64 " +
                             std::to_string(statement.location.column) + ")\n";
            if (!statement.keyName.empty()) {
                const auto keyDataAddress = newTemporary();
                const auto keyData = newTemporary();
                const auto keyLengthAddress = newTemporary();
                const auto keyLength = newTemporary();
                instructions_ += "  " + keyDataAddress +
                                 " = getelementptr inbounds %CwhipMapEntry, ptr " + entry +
                                 ", i32 0, i32 0\n"
                                 "  " + keyData + " = load ptr, ptr " + keyDataAddress + "\n"
                                 "  " + keyLengthAddress +
                                 " = getelementptr inbounds %CwhipMapEntry, ptr " + entry +
                                 ", i32 0, i32 1\n"
                                 "  " + keyLength + " = load i64, ptr " + keyLengthAddress +
                                 "\n";
                // Map keys are stored as raw bytes; each iteration materializes
                // a fresh String for the loop binding.
                const auto keyObject =
                    emitStringFromBytes(keyData, keyLength, statement.location);
                instructions_ += "  store ptr " + keyObject.operand + ", ptr " +
                                 scopes_.back().at(statement.keyName).pointer + "\n";
            }
            instructions_ += "  " + valueAddress +
                             " = getelementptr inbounds %CwhipMapEntry, ptr " + entry +
                             ", i32 0, i32 3\n"
                             "  " + value + " = load %CwhipArrayValue, ptr " + valueAddress +
                             "\n"
                             "  store %CwhipArrayValue " + value + ", ptr " + valueSlot +
                             "\n";
        }
        loopTargets_.push_back({endLabel, stepLabel, activeTryTransfers_.size()});
        blockTerminated_ = false;
        emitStatements(statement.body);
        const bool bodyTerminated = blockTerminated_;
        loopTargets_.pop_back();
        scopes_.pop_back();
        if (!bodyTerminated) instructions_ += "  br label %" + stepLabel + "\n";
        instructions_ += stepLabel + ":\n";
        blockTerminated_ = false;
        const auto currentIndex = newTemporary();
        const auto nextIndex = newTemporary();
        instructions_ += "  " + currentIndex + " = load i64, ptr " + indexSlot + "\n"
                         "  " + nextIndex + " = add i64 " + currentIndex + ", 1\n"
                         "  store i64 " + nextIndex + ", ptr " + indexSlot + "\n"
                         "  br label %" + conditionLabel + "\n";
        instructions_ += endLabel + ":\n";
        blockTerminated_ = false;
        return;
    }
    case StatementKind::Raise: {
        if (statement.rethrowsException) {
            instructions_ += "  call void @cwhip_exception_rethrow(ptr " +
                             activeExceptionHandlers_.back() + ")\n"
                             "  unreachable\n";
            blockTerminated_ = true;
            return;
        }
        const auto value = emitExpression(*statement.expressions.front());
        const auto* owner = classes_.at(value.type);
        std::vector<std::size_t> messagePath;
        const auto* messageField = findField(*owner, "message", messagePath);
        if (messageField == nullptr) {
            throw DiagnosticError(statement.location,
                                  "exception class has no inherited message field");
        }
        const auto messageAddress = emitFieldAddress(value.operand, *owner, messagePath);
        const auto message = newTemporary();
        instructions_ += "  " + message + " = load ptr, ptr " + messageAddress + "\n";
        // A raised exception may carry a null message; the runtime accepts an
        // empty byte range, so avoid faulting on the borrow in that case.
        const auto dataSlot = "%raise.data." + std::to_string(nextVariable_++);
        const auto lengthSlot = "%raise.length." + std::to_string(nextVariable_++);
        entryAllocas_ += "  " + dataSlot + " = alloca ptr\n"
                         "  " + lengthSlot + " = alloca i64\n";
        const auto messageIsNull = newTemporary();
        const auto messageNullLabel = freshLabel("raise.message.null");
        const auto messageBytesLabel = freshLabel("raise.message.bytes");
        const auto messageEndLabel = freshLabel("raise.message.end");
        instructions_ += "  store ptr null, ptr " + dataSlot + "\n"
                         "  store i64 0, ptr " + lengthSlot + "\n"
                         "  " + messageIsNull + " = icmp eq ptr " + message + ", null\n"
                         "  br i1 " + messageIsNull + ", label %" + messageNullLabel +
                         ", label %" + messageBytesLabel + "\n" + messageBytesLabel + ":\n"
                         "  call void @cwhip_string_bytes(ptr " + message + ", ptr " +
                         dataSlot + ", ptr " + lengthSlot + ")\n"
                         "  br label %" + messageEndLabel + "\n" + messageNullLabel + ":\n"
                         "  br label %" + messageEndLabel + "\n" + messageEndLabel + ":\n";
        const auto data = newTemporary();
        const auto length = newTemporary();
        instructions_ += "  " + data + " = load ptr, ptr " + dataSlot + "\n"
                         "  " + length + " = load i64, ptr " + lengthSlot + "\n";
        const auto exceptionSubobjects = subobjects(*owner);
        const auto base = std::find_if(
            exceptionSubobjects.begin(), exceptionSubobjects.end(),
            [](const auto& subobject) { return subobject.second->name == "Exception"; });
        if (base == exceptionSubobjects.end()) {
            throw DiagnosticError(statement.location,
                                  "raised class is not in the Exception hierarchy");
        }
        const auto exceptionView = emitSubobjectAddress(value.operand, *owner, base->first);
        const auto file = internString(statement.location.file);
        instructions_ +=
            "  call void @cwhip_exception_raise_object(ptr " + value.operand + ", ptr " +
            exceptionView + ", ptr " + data + ", i64 " + length + ", ptr " + file +
            ", i64 " + std::to_string(statement.location.file.size()) + ", i64 " +
            std::to_string(statement.location.line) + ", i64 " +
            std::to_string(statement.location.column) + ")\n"
            "  unreachable\n";
        blockTerminated_ = true;
        return;
    }
    case StatementKind::Try:
        emitTry(statement);
        return;
    case StatementKind::Break:
        emitLoopTransfer(true, statement.location);
        return;
    case StatementKind::Continue:
        emitLoopTransfer(false, statement.location);
        return;
    }
}

} // namespace cwhip
